template <typename T, typename U>
class GenericType {}; // Primary Template

// 1. Full Specialization (T=int, U=double)
template <>
class GenericType<int, double> {
    int val;
    double data;
};

// 2. Partial Specialization (T is a Pointer)
template <typename V, typename U>
class GenericType<V*, U> {
    V* ptr;
};

// 3. Partial Specialization (T and U are the same type)
template <typename T>
class GenericType<T, T> {
    T item;
};
